function [dj, de] = secular_rates(j, e, nhat, phi_q, np)
%SECULAR_RATES  The rates of j and e summed over np perturbers (their poles and secular frequencies; at most TB_NP).
%   j: real[1][3] (passed a plain number)
%   e: real[1][3] (passed a plain number)
%   nhat: real[1][3][TB_NP] (passed a plain number)
%   phi_q: real[1][TB_NP] (passed a plain number)
%   np: int (passed a whole number)
%   returns dj: real[1][3] (passed a plain number)
%   returns de: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    dj = zeros(3, 1);
    de = zeros(3, 1);
    dj = zeros(3, 1);
    de = zeros(3, 1);
    for m = (0):((np) - 1)
        [d1, d2] = asils.models.thirdbody.kozai_rates(j, e, (nhat((m) + 1, :)).', phi_q((m) + 1));
        i = ((0):((3) - 1)).';
        dj((i) + 1) = (reshape(dj((i) + 1), [], 1) + reshape(d1((i) + 1), [], 1));
        de((i) + 1) = (reshape(de((i) + 1), [], 1) + reshape(d2((i) + 1), [], 1));
    end
end
